import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { phonePlans } from '../config/phonePlanConfig';
import PhoneSalesFilterForm from './PhoneSalesFilterForm';
import PhoneSalesInputForm from './PhoneSalesInputForm';
import PhoneSalesResult from './PhoneSalesResult';

export default function PhoneSalesCalculator() {
  const navigate = useNavigate();
  const [values, setValues] = useState({
    dataFilter: '',
    category: '',
    planId: '',
    planCost: 0,
    devicePrice: 0,
    partialPayment: 0,
    subsidyAmount: 0,
    discountType: '',
    installments: 24,
  });
  const [results, setResults] = useState({
    monthlyPlanCost: 0,
    deviceInstallment: 0,
    totalPayment: 0,
    savings: 0,
  });
  const [showResult, setShowResult] = useState(false);
  const [recommendedDiscount, setRecommendedDiscount] = useState('');
  const monthlyRate = 0.059 / 12;

  const handleFilterChange = (name, value) => {
    setValues(prev => {
      const next = { ...prev, [name]: value };
      if (name === 'dataFilter') {
        next.category = '';
        next.planId = '';
        next.planCost = 0;
      }
      if (name === 'category') {
        next.planId = '';
        next.planCost = 0;
      }
      if (name === 'planId') {
        const plan = phonePlans.find(p => p.id === value);
        next.planCost = plan ? plan.monthlyFee : 0;
      }
      return next;
    });
    setShowResult(false);
    setRecommendedDiscount('');
  };

  const handleChange = e => {
    const { name, value } = e.target;
    setValues(prev => ({
      ...prev,
      [name]: ['installments','partialPayment','subsidyAmount'].includes(name)
        ? Number(value)
        : value,
    }));
    setShowResult(false);
    setRecommendedDiscount('');
  };

  const calculate = () => {
    const { devicePrice, partialPayment, planCost, subsidyAmount, discountType, installments } = values;
    if (!planCost) return;
    // 기본 원금
    const basePrincipal = devicePrice - partialPayment;
    // 1) 요금할인 시나리오 원금
    const principalContract = basePrincipal;
    // 2) 공시지원금 시나리오 원금
    const principalSubsidy = basePrincipal - subsidyAmount;

    // 요금할인 시나리오: 월 요금제 + 할부
    const planContract = Math.round(planCost * 0.75);
    const deviceContract = installments > 0
      ? Math.ceil((principalContract * monthlyRate) / (1 - Math.pow(1 + monthlyRate, -installments)))
      : 0;
    const totalContract = planContract + deviceContract;

    // 공시지원금 시나리오: 월 요금제 + 할부
    const planSubsidy = planCost;
    const deviceSubsidy = installments > 0
      ? Math.ceil((principalSubsidy * monthlyRate) / (1 - Math.pow(1 + monthlyRate, -installments)))
      : 0;
    const totalSubsidy = planSubsidy + deviceSubsidy;

    // ③ 사용자 선택 결과
    const monthlyPlanCost = discountType === 'contract' ? planContract : planSubsidy;
    const deviceInstallment = discountType === 'contract' ? deviceContract : deviceSubsidy;
    const totalPayment = discountType === 'contract' ? totalContract : totalSubsidy;

    // ④ 절감/손해액 = 대안 시나리오 총납부 - 선택 시나리오 총납부
    const savings = (discountType === 'contract' ? totalSubsidy - totalContract : totalContract - totalSubsidy);

    // ⑤ 추천 할인: 더 적은 총납부를 주는 시나리오를 추천
    const recommended = totalContract < totalSubsidy ? '요금할인' : '공시 지원금';

    setResults({ monthlyPlanCost, deviceInstallment, totalPayment, savings });
    setRecommendedDiscount(recommended);
    setShowResult(true);
  };

  return (
    <div className="flex flex-col items-center min-h-screen bg-gray-50 p-4">
      <div className="w-full max-w-lg bg-white shadow rounded-2xl p-6 mb-4">
        <h2 className="text-2xl font-bold mb-6 text-center">KT 핸드폰 상담 계산기</h2>

   {/* 경고 문구 */}
    <p className="mt-2 text-base font-bold text-red-500">주의! 본 견적은 가 견적이오니, 정확한 견적은 필히 추가로 확인하셔야 합니다.</p>
        <PhoneSalesFilterForm values={values} onFilterChange={handleFilterChange} />
        <PhoneSalesInputForm
          values={values}
          onChange={handleChange}
          others={phonePlans.find(p => p.id === values.planId)?.others}
          recommendedDiscount={recommendedDiscount}
        />

        <button
          type="button"
          onClick={calculate}
          className="w-full bg-blue-500 text-white py-2 rounded-md hover:bg-blue-600 transition mb-4"
        >
          계산하기
        </button>

        {showResult && <PhoneSalesResult {...results} discountType={values.discountType} />}

        <div className="mt-2 w-full text-center">
          <button
            onClick={() => navigate('/')}
            className="w-full px-4 py-2 bg-gray-200 rounded hover:bg-gray-300"
          >
            메인 메뉴로 돌아가기
          </button>
        </div>
      </div>
    </div>
  );
}